window.kbPageData["views/entry/k-c454c530ac6293ee"] = {"key":"entry/k-c454c530ac6293ee","state":{"route":"entry/k-c454c530ac6293ee"},"node":{"id":"k-c454c530ac6293ee","mode":"k","title":"“火焰”与“火气”中的“火”","type":"概念与词义","domain":"汉语","reading":"","intro":"","priority":100,"aliases":["“火焰”的“火”指燃烧产生的光和焰，“火气”的“火”由火引申为怒气或暴躁的脾气"],"qs":["江苏 2024 C类 行测#69"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"“火焰”的“火”取物体燃烧的本义。“火气”在本题取怒气、易动怒的脾气这一义项，由火的炽烈引申。","review":{"definition":"“火焰”的“火”取物体燃烧的本义。“火气”在本题取怒气、易动怒的脾气这一义项，由火的炽烈引申。","explanation":"题干的“海沟”直接指涉海洋，“海量”借海的广大形容量大。C项的“火焰”直接指涉燃烧，“火气”借火的炽烈表达怒气，语素层面的对应更具体。辞书也收录“心腹”的身体部位义和亲信义，说明D项同样有引申现象。若只比较后一个词有没有引申义，区分不了C和D。题解选择C所用的更细标准，是比较首字本义所指事物的特征是否直接用来形容后一个词的含义。","references":[{"source":"web-ef742bceaed7dd98","location":"“心腹”条，释义第4项","quote":"親信可靠的人"},{"source":"web-c6be0cc52b2248e5","location":"“火氣”条，释义第2项","quote":"脾氣不佳，遇事容易動怒"}],"evidence":"“火气”多指怒气、暴躁的脾","disposition":"题内说明","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2024 C类 行测#69":{"paper":"江苏 2024 C类 行测","n":69,"mod":"判断推理","src":["3f1ec77ae8a18519b57e.pdf",12],"asrc":["02d6b49839583bdaf297.pdf",20],"card":"7399304ab35ea0501c1f4cd4","links":[{"id":"k-c454c530ac6293ee","role":"解题依据","why":"识别“火气”中“火”的引申用法才能比对两个词的语素义。"}]}},"terms":{},"references":{"web-ef742bceaed7dd98":{"name":"教育部《重編國語辭典修訂本》","url":"https://dict.revised.moe.edu.tw/dictView.jsp?ID=108637"},"web-c6be0cc52b2248e5":{"name":"教育部《重編國語辭典修訂本》","url":"https://dict.revised.moe.edu.tw/dictView.jsp?ID=84312&la=1&powerMode=0"}},"topics":[],"units":{"k-c454c530ac6293ee":[["江苏 2024 C类 行测#69"]]}};
